// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _val, uint _lockTime, uint _am) public {
        // Initialize the contract
        c.SetMinSum(_val);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Record MinSum
        uint initialMinSum = c.MinSum();

        // Drive through a Collect call (may revert)
        // Fund the contract to enable Collect
        vm.deal(address(this), 1 ether);
        c.Put{value: 1 ether}(_lockTime);

        // Warp to unlock time
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect with bounded am
        uint bal = c.Acc(address(this)).balance;
        uint minSum = c.MinSum();
        vm.assume(_am <= bal);
        vm.assume(bal >= minSum);

        c.Collect(_am);

        // Assert: MinSum is invariant
        assertTrue(c.MinSum() == initialMinSum);
    }
}

