pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSumVal, uint256 collectAm, uint256 preLockTime, uint256 sendVal) public {
        // Bound inputs to avoid overflow/revert in reference
        minSumVal = bound(minSumVal, 1, type(uint256).max - 1); // ensure subtracting 1 is safe for reference
        collectAm = bound(collectAm, 1, type(uint256).max - 1);
        preLockTime = bound(preLockTime, 0, 1000);
        sendVal = bound(sendVal, 0, 1 ether);

        // Setup: set MinSum and initialize
        vm.deal(address(this), sendVal);
        c.SetMinSum(minSumVal);
        c.Initialized();

        // Record MinSum after initialization
        uint256 minSumAfterInit = c.MinSum();

        // Drive a Put then Collect
        c.Put{value: sendVal}(preLockTime);
        // warp to after unlock
        vm.warp(block.timestamp + preLockTime + 1);
        (bool succ,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAm));

        // Rule: MinSum must not decrease from post-init value
        assertTrue(c.MinSum() >= minSumAfterInit);
    }
}

