pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am, uint256 _depositAmount) public {
        // Restrict to valid inputs: set MinSum, log, initialize, then deposit and call Collect
        vm.assume(_val > 0); // to avoid underflow in buggy version
        vm.assume(_val < 1e30);
        vm.assume(_lockTime < 1e10);
        vm.assume(_am < 1e10);
        vm.assume(_depositAmount < 1e10);

        // Setup
        c.SetMinSum(_val);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        uint256 minSumBefore = c.MinSum();

        // Deposit to the contract (fallback calls Put(0))
        vm.deal(address(this), _depositAmount);
        (bool depositSuccess,) = address(c).call{value: _depositAmount}("");
        vm.assume(depositSuccess);

        // Try to collect
        vm.startPrank(address(this));
        (bool collectSuccess,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        vm.stopPrank();

        // No revert difference: just assert state
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter == minSumBefore, "MinSum changed after Collect");
    }
}

