pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 amount, uint256 deposit) public {
        // Restrict inputs to avoid assertion failures due to overflow/underflow
        vm.assume(minSum >= 1 && minSum <= type(uint256).max - 1);
        vm.assume(lockTime <= type(uint256).max - block.timestamp - 1);
        vm.assume(amount <= type(uint256).max);
        vm.assume(deposit >= amount && deposit <= address(this).balance);

        // Set MinSum
        c.SetMinSum(minSum);
        // Record the initial MinSum as set (before initialization)
        uint256 originalMinSum = minSum; // reference sets MinSum = _val; mutant sets MinSum = _val - 1

        // Initialize
        c.Initialized();

        // Provide funds and deposit
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(lockTime);

        // Warp past unlock time to allow Collect
        vm.warp(block.timestamp + lockTime + 1);

        // Attempt Collect
        c.Collect(amount);

        // The general rule: after all operations, MinSum must equal originalMinSum (for reference) or originalMinSum - 1 (for mutant)
        // Since we cannot distinguish internally, we assert that MinSum == originalMinSum for the reference.
        assertTrue(c.MinSum() == originalMinSum);
    }
}

