pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _putValue, uint256 _collectAm) public {
        // First, call Initialized to move past the guard (for P, SetMinSum reverts after init; for M, it reverts before init)
        c.Initialized();
        // Give some ether to the contract
        vm.deal(address(c), 1 ether);
        // Put some value and lock time
        vm.deal(address(this), _putValue);
        c.Put{value: _putValue}(_lockTime);
        // Now attempt Collect — the guard in SetMinSum is irrelevant to Collect, but the difference is about the state after init
        // We'll just call Collect to see if it changes anything; but the core difference is in SetMinSum's guard
        c.Collect(_collectAm);
        // The general rule: after Initialized() has been called, c.MinSum() must still be 0 (default) because SetMinSum was never called and would revert after init in P, but in M it would revert before init, so MinSum is unchanged
        // In both cases MinSum remains 0, but the guard direction differs: in P, SetMinSum reverts after init; in M, SetMinSum reverts before init.
        // So for any inputs, after calling Initialized, calling SetMinSum should revert. We test that by trying a call and asserting it reverts.
        vm.expectRevert();
        c.SetMinSum(100);
    }
}

