        vm.assume(initialMinSum <= 1e30);

        // Set initial MinSum from the contract state (default 0) or via deployment
        // We'll just use the default MinSum which is 0

        // First, we need to avoid the revert in Put due to overflow; restrict values
        vm.assume(_lockTime <= 1e12);  // Reasonable lock time

        // We'll call Put first to ensure balance > 0 for Collect to potentially trigger
        vm.deal(address(this), 1 ether);
        c.Put{value: 1 ether}(_lockTime);

        // Record MinSum before Collect call
        uint256 minSumBefore = c.MinSum();

        // Attempt to call Collect (may revert or not)
