pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 amount, uint256 minSum) public {
        // Restrict inputs to avoid reverts that are irrelevant
        vm.assume(lockTime <= type(uint256).max - block.timestamp); // avoid overflow in unlockTime
        vm.assume(amount > 0 && amount <= 1e18); // reasonable amounts
        vm.assume(minSum <= 1e18);

        // Try to call SetMinSum (will always revert in reference before Initialized)
        (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", minSum));

        // The reference guarantees SetMinSum reverts before Initialized
        // So MinSum should stay 0
        // Initialize the contract
        c.Initialized();

        // Put some funds
        vm.deal(address(this), amount);
        c.Put{value: amount}(lockTime);

        // Warp past unlock time to allow Collect
        vm.warp(block.timestamp + lockTime + 1);

        // Call Collect with an amount <= balance and >= MinSum (but MinSum is 0)
        if (amount > 0) {
            (bool collectSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
            collectSuccess; // unused
        }

        // The rule: MinSum must be 0 (it was never changed because SetMinSum always reverts before init)
        assertTrue(c.MinSum() == 0);
    }
}

