pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, address caller, uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        // Bound minSum to avoid overflow issues
        vm.assume(minSum <= type(uint256).max / 2);
        // Set MinSum via SetMinSum - note: both reference and mutant accept the parameter, but mutant ignores it
        if (minSum > 0) {
            // Ensure we call SetMinSum only once before initialization
            if (address(c).code.length > 0) {
                // Deploy fresh contract to ensure uninitialized state
                c = new C();
            }
            c.SetMinSum(minSum);
            c.Initialized();
        }

        // Perform some Put operations
        vm.deal(caller, putAmount + 1 ether);
        vm.prank(caller);
        if (putAmount > 0) {
            c.Put{value: putAmount}(lockTime);
        }

        // Try Collect
        uint256 initialBalance = address(caller).balance;
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: if SetMinSum was called with some value, MinSum should equal that value
        // The mutant sets MinSum = 0 regardless of input, so reference will have MinSum = minSum (if called with minSum > 0)
        // For the reference: MinSum == minSum (if minSum > 0) or MinSum == 0 (if minSum == 0, default)
        // For the mutant: MinSum == 0 always
        assertTrue(c.MinSum() == (minSum > 0 ? minSum : 0));
    }
}

