pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val) public {
        // Call SetMinSum once with any value (including 0)
        c.SetMinSum(val);
        uint256 expected = val; // After first call, MinSum should be val
        // If val > 0, reference sets MinSum = val, bug sets to 0 (so fails)
        // If val == 0, both set to 0, but we need a general rule that fails for bug when val != 0
        // To make it general, we restrict val > 0: bug always sets to 0, so rule holds
        vm.assume(val > 0);
        // Now call Initialized to prevent further SetMinSum (mimicking mutex)
        c.Initialized();
        // Attempt to call SetMinSum again should revert
        vm.expectRevert();
        c.SetMinSum(42);
        // Call Put to enable Collect (balance >= MinSum + 1)
        vm.deal(address(this), 1 wei);
        c.Put{value: 1 wei}(0); // unlockTime = 0, block.timestamp > 0 after warp
        vm.warp(block.timestamp + 1); // ensure time > unlockTime
        // Collect enough to succeed (balance = 1, MinSum = expected, so balance >= MinSum)
        // Actually balance = 1, MinSum = expected > 0, so need balance >= MinSum: but we only have 1 wei; for expected>1, condition fails
        // Simplify: assume val = 1 so that 1 >= 1 passes
        vm.assume(val == 1);
        c.Collect(1);
        // After Collect, MinSum should be unchanged from expected
        assertTrue(c.MinSum() == val, "MinSum should remain unchanged");
    }
}

