pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint lockTime, uint putAmount, uint collectAmount) public {
        vm.assume(putAmount > 0 && putAmount <= type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        vm.assume(lockTime <= type(uint40).max);

        // Initialize the contract
        c.SetMinSum(0);
        c.Initialized();

        // Deposit via Put
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(lockTime);

        // Fast forward past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Record balances before Collect
        (uint unlockTimeBefore, uint accBalanceBefore) = c.Acc(caller);
        uint contractBalanceBefore = address(c).balance;

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // After Collect, read account balance and contract balance
        (uint unlockTimeAfter, uint accBalanceAfter) = c.Acc(caller);
        uint contractBalanceAfter = address(c).balance;

        // Sum of all account balances (we only have one caller's account, but contract can have many)
        // The sum of all balances in Acc mappings is at least accBalanceAfter
        // The contract balance should never exceed the total of all account balances
        if (success) {
            // After successful Collect, the caller's balance in Acc decreased by collectAmount
            // Contract balance decreased by collectAmount as well
            // So: contractBalanceAfter <= accBalanceAfter + (any other accounts' balances)
            // Since we only have this caller, it's exactly contractBalanceAfter == accBalanceAfter
            assertTrue(address(c).balance >= c.Acc(caller).balance);
        } else {
            // If revert, balances unchanged
            assertTrue(contractBalanceAfter <= accBalanceAfter + (contractBalanceAfter - accBalanceAfter));
        }
    }
}

