        vm.deal(caller, initialBalance);
        vm.prank(caller);
        (bool okPut, ) = address(c).call{value: initialBalance}(abi.encodeWithSignature("Put(uint256)", lockTime));
        vm.assume(okPut);
        c.SetMinSum(minSum);
        c.Initialized();
        // Advance time past unlock
        vm.warp(block.timestamp + lockTime + 1);
        vm.prank(caller);
        (bool okCollect, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));
        // The reference ensures that if am > balance, Collect reverts.
        // The buggy version allows withdrawal even if am > balance, causing underflow.
        bool expectedRevert = (am > initialBalance);
        assertTrue(okCollect == !expectedRevert);
    }
}

