pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 _lockTime, uint256 putValue, uint256 minSum, uint256 _am) public {
        vm.assume(sender != address(0) && sender != address(c));
        vm.assume(putValue > 0 && putValue < type(uint256).max / 2);
        vm.assume(_am > 0 && _am <= putValue);
        vm.assume(minSum > 0 && minSum <= putValue);

        vm.deal(sender, putValue + 1 ether);
        vm.prank(sender);
        c.SetMinSum(minSum);
        c.Initialized();

        vm.prank(sender);
        c.Put{value: putValue}(_lockTime);

        uint256 balanceBefore = c.Acc(sender).balance;

        vm.warp(block.timestamp + _lockTime + 1);

        vm.prank(sender);
        c.Collect(_am);

        uint256 balanceAfter = c.Acc(sender).balance;

        // The reference only subtracts _am if balance >= _am (the removed condition)
        // So the invariant is: balanceAfter is never less than balanceBefore - _am
        assertTrue(balanceAfter >= balanceBefore - _am);
    }
}
